import json, time

async def main(args):
    raw = args.params.get("cache_raw")
    if isinstance(raw, str):
        try:
            raw = json.loads(raw)
        except Exception:
            raw = {}
    if not isinstance(raw, dict):
        raw = {}
    hit, val = raw.get("hit"), raw.get("value")
    fresh, text = False, ""
    try:
        if hit and val:
            d = json.loads(val) if isinstance(val, str) else val
            ts = float((d or {}).get("ts") or 0)
            if time.time() - ts < 300 and (d or {}).get("text"):
                fresh, text = True, d["text"]
    except Exception:
        fresh = False
    return {"fresh": fresh, "text": text}

import json, time

async def main(args):
    raw = args.params.get("raw")
    if isinstance(raw, dict):
        text = str(raw.get("raw") or raw.get("result") or raw)
    else:
        text = str(raw or "")
    if not text.strip():
        text = "（SCNet 状态为空）"
    payload = json.dumps({"ts": time.time(), "text": text}, ensure_ascii=False)
    return {"status_text": text, "cache_payload": payload}
